import { createBroadcastHandler, options } from 'dhcp';

const watcher = createBroadcastHandler({ logLevel: 'silent' });

watcher.on('message', (packet) => {

    const messageType = packet.options[53];

    process.stdout.write(`${JSON.stringify({
        time: new Date().toISOString(),
        client: packet.chaddr,
        type: options[53].enum[messageType] ?? messageType,
        requestedAddress: packet.options[50],
        offeredAddress: packet.yiaddr === '0.0.0.0' ? undefined : packet.yiaddr,
        server: packet.options[54],
        hostname: packet.options[12],
        vendorClass: packet.options[60],
    })}\n`);
});

watcher.listen();
